double math_det3(pc_a3a3f m);

typedef struct { pc_a3a3f r; bool ok; } math_inv3_out;

/* The inverse by the adjugate; a singular matrix (|det| < 1e-300) gives zeros and ok = false. */
/* - m */
/* - returns r */
