/* - returns s */
/* - returns wr */
/* - returns we */
control_mtq_err_out control_mtq_err(pc_a4f q, pc_a3f w, pc_a4f q_ref, pc_a3f w_ref);

/* P1 Lovera & Astolfi 2004: u = -(eps^2 k_p q_v + eps k_v J w_e). */
/* - q */
/* - w */
/* - q_ref */
/* - w_ref */
/* - j */
/* - eps */
/* - kp */
/* - kv */
