pc_a3f control_mtq_lovera(pc_a4f q, pc_a3f w, pc_a4f q_ref, pc_a3f w_ref, pc_a3a3f j, double eps, double kp, double kv);

/* P4 Celani 2015: u = -(eps^2 k1 q_v + eps k2 w_e). */
/* - q */
/* - w */
/* - q_ref */
/* - w_ref */
/* - eps */
/* - k1 */
/* - k2 */
