pc_a3f control_mtq_celani(pc_a4f q, pc_a3f w, pc_a4f q_ref, pc_a3f w_ref, double eps, double k1, double k2);

typedef struct { pc_a3f tau; bool ok; } control_mtq_avanzini_out;

/* P16 Avanzini, de Angelis & Giulietti 2021: the pitch axis spun at the reference rate and aligned */
/* with the orbit normal, the pitch error removed slowly. ok = false (and no torque) when the */
/* reference does not rotate. */
/* - q */
/* - w */
/* - q_ref */
/* - w_ref */
/* - j */
/* - k */
/* - lam */
/* - returns tau */
/* - returns ok */
control_mtq_avanzini_out control_mtq_avanzini(pc_a4f q, pc_a3f w, pc_a4f q_ref, pc_a3f w_ref, pc_a3a3f j, double k, double lam);

/* P8 Celani 2026: the boresight e3 onto the target a, the roll about e3 left free: */
/* tau = k_p (e3 x a) - k_d w_e. */
/* - e3 */
/* - a */
/* - we */
/* - kp */
/* - kd */
/* - returns tau */
pc_a3f control_mtq_boresight(pc_a3f e3, pc_a3f a, pc_a3f we, double kp, double kd);

/* P3 TANGO (Chasset et al. 2013): LQR with P frozen at the averaged Riccati solution: */
/* tau = -(P_th theta + P_w w_e), theta = 2 s q_v. */
/* - q */
/* - w */
/* - q_ref */
/* - w_ref */
/* - pth */
/* - pw */
/* - returns tau */
pc_a3f control_mtq_tango(pc_a4f q, pc_a3f w, pc_a4f q_ref, pc_a3f w_ref, pc_a3a3f pth, pc_a3a3f pw);

