typedef struct { bool mag_ok; pc_a3f b; bool gyro_ok; pc_a3f w; bool sun_ok; pc_a3f sun; bool es_ok; pc_a3f nadir; bool st_ok; pc_a2b st_valid; pc_a2a4f q_st; bool gps_ok; pc_a3f r; pc_a3f v; pc_a8f h; pc_a4f delta; } drivers_drv_read_out;

